import test from 'node:test';
import assert from 'node:assert/strict';
import { loadStandaloneTypeScript } from './patchproof_runtime/typescript_module.mjs';

const { formatBytes, formatSpeed, formatEta } = loadStandaloneTypeScript('lib/utils/format.ts');

test('formatBytes returns literal fragments on values >= 1024', () => {
  assert.equal(formatBytes(512), '512 B');
  assert.equal(formatBytes(1024), '1.0 KB');
  assert.equal(formatBytes(1536), '1.5 KB');
  assert.equal(formatBytes(102400), '100 KB');
  assert.equal(formatBytes(1048576), '1.0 MB');
  assert.equal(formatBytes(1073741824), '1.0 GB');
});

test('formatSpeed inherits literal fragments', () => {
  assert.equal(formatSpeed(1536), '1.5 KB/s');
});

test('formatEta remains unaffected', () => {
  assert.equal(formatEta(0), '0s');
  assert.equal(formatEta(1.2), '2s');
  assert.equal(formatEta(Infinity), '—');
});

